const MEASURE_COLUMNS = [
  // pageviews (migration 005) is what makes a row exist at all before any experiment runs: it is both
  // a measure and the fallback denominator behind cta_ctr / buy_click_rate / purchase_rate while an
  // arm has no exposures. cms-agent's engagement.v1 metric vector carries it under the same name.
  "pageviews",
  "exposures",
  "sessions",
  "completion_rate",
  "cta_ctr",
  "buy_click_rate",
  "purchase_rate",
  "revenue_cents",
  "p75_dwell_ms",
] as const;

export function shapeProducerRow(row: Record<string, unknown>): ProducerRollupRow {
  return {
    run_id: row.run_id === null || row.run_id === undefined ? null : String(row.run_id),
    node_id: row.node_id === null || row.node_id === undefined ? null : String(row.node_id),
    prompt_version: row.prompt_version === null || row.prompt_version === undefined ? null : String(row.prompt_version),
    day: toDay(row.day),
    ...shapeMeasures(row),
  };
}
